    /*
     * Add to the Positions
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Department
     */
    public Department addToPositions( UUID parentId, Position addTo ) {
	    LOGGER.info("handling AssignPositionsToDepartmentEvent - " );
	    
	    Department parentEntity = repository.findById(parentId).get();
	    Position child = registry.project( Position.class, addTo.getPositionId());
	    
	    parentEntity.getPositions().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Positions
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Department
     */
	public Department removeFromPositions( UUID parentId, Position removeFrom ) {
	    LOGGER.info("handling RemovePositionsFromDepartmentEvent " );
	
	    Department parentEntity = repository.findById(parentId).get();
	    Position child = registry.project( Position.class, removeFrom.getPositionId());
	    
	    parentEntity.getPositions().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}

